changeSet.sql:
ALTER TABLE public.team_item_version ADD CONSTRAINT ck_team_item_version_state
    CHECK (state IN ('AVAILABLE', 'WITHDRAWN', 'EXPIRED', 'ERASED'));
-- Only an erasure removes the submitter, and it always does, so no version is detached from it before.
ALTER TABLE public.team_item_version ADD CONSTRAINT ck_team_item_version_submitter
    CHECK ((state = 'ERASED') = (submitted_by IS NULL));
-- The title is submitted content: it exists only while the version is available.
ALTER TABLE public.team_item_version ADD CONSTRAINT ck_team_item_version_title
    CHECK (state = 'AVAILABLE' OR title IS NULL);

changeSet.createProcedure:
CREATE FUNCTION public.admit_team_item() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    PERFORM 1 FROM public.project_team t
        WHERE t.id = NEW.team_id AND t.workspace_id = NEW.workspace_id AND t.removed_at IS NULL
        FOR SHARE;
    IF NOT FOUND OR NEW.removed_at IS NOT NULL THEN
        RAISE EXCEPTION 'a team item needs a standing project team' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END $$

CREATE FUNCTION public.guard_team_item() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF ROW(NEW.id, NEW.workspace_id, NEW.team_id, NEW.kind, NEW.created_at)
        IS DISTINCT FROM ROW(OLD.id, OLD.workspace_id, OLD.team_id, OLD.kind, OLD.created_at)
        OR (OLD.removed_at IS NOT NULL AND NEW.removed_at IS DISTINCT FROM OLD.removed_at) THEN
        RAISE EXCEPTION 'a team item keeps its identity, and a removed item stays removed' USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
END $$

CREATE FUNCTION public.withdraw_removed_team_item() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    UPDATE public.team_item_version v SET state = 'WITHDRAWN', title = NULL
        WHERE v.item_id = NEW.id AND v.workspace_id = NEW.workspace_id AND v.state = 'AVAILABLE';
    RETURN NULL;
END $$

CREATE FUNCTION public.remove_items_of_removed_project_team() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    UPDATE public.team_item i SET removed_at = NEW.removed_at
        WHERE i.team_id = NEW.id AND i.workspace_id = NEW.workspace_id AND i.removed_at IS NULL;
    RETURN NULL;
END $$

CREATE FUNCTION public.admit_team_item_version() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
    item_team uuid;
BEGIN
    IF NEW.state != 'AVAILABLE' THEN
        RAISE EXCEPTION 'a new team item version is available' USING ERRCODE = '23514';
    END IF;
    PERFORM 1 FROM public.account a WHERE a.id = NEW.submitted_by AND a.status = 'ACTIVE' FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'a team item version needs an active account' USING ERRCODE = '23514';
    END IF;
    SELECT i.team_id INTO item_team FROM public.team_item i
        WHERE i.id = NEW.item_id AND i.workspace_id = NEW.workspace_id;
    PERFORM 1 FROM public.project_team_member m
        WHERE m.team_id = item_team AND m.workspace_id = NEW.workspace_id AND m.account_id = NEW.submitted_by
        FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'a team item version needs a member of the item''s team' USING ERRCODE = '23514';
    END IF;
    PERFORM 1 FROM public.project_team t
        WHERE t.id = item_team AND t.workspace_id = NEW.workspace_id AND t.removed_at IS NULL FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'a team item version needs a standing project team' USING ERRCODE = '23514';
    END IF;
    PERFORM 1 FROM public.team_item i
        WHERE i.id = NEW.item_id AND i.workspace_id = NEW.workspace_id AND i.removed_at IS NULL FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'a team item version needs a standing item' USING ERRCODE = '23514';
    END IF;
    NEW.created_in_transaction := pg_current_xact_id()::text::bigint;
    RETURN NEW;
END $$

changeSet.rollback:
DROP FUNCTION public.withdraw_departed_team_member_versions();
DROP FUNCTION public.guard_team_item_version();
DROP FUNCTION public.admit_team_item_version();
DROP FUNCTION public.remove_items_of_removed_project_team();
DROP FUNCTION public.withdraw_removed_team_item();
DROP FUNCTION public.guard_team_item();
DROP FUNCTION public.admit_team_item();

changeSet.sql:
CREATE TRIGGER team_item_version_admit BEFORE INSERT ON public.team_item_version
    FOR EACH ROW EXECUTE FUNCTION public.admit_team_item_version();
CREATE TRIGGER team_item_version_guard AFTER UPDATE ON public.team_item_version
    FOR EACH ROW EXECUTE FUNCTION public.guard_team_item_version();

CREATE TRIGGER team_item_admit BEFORE INSERT ON public.team_item
    FOR EACH ROW EXECUTE FUNCTION public.admit_team_item();
CREATE TRIGGER team_item_guard AFTER UPDATE ON public.team_item
    FOR EACH ROW EXECUTE FUNCTION public.guard_team_item();
CREATE TRIGGER team_item_removed AFTER UPDATE OF removed_at ON public.team_item
    FOR EACH ROW WHEN (NEW.removed_at IS NOT NULL) EXECUTE FUNCTION public.withdraw_removed_team_item();

changeSet.rollback:
DROP TRIGGER team_item_removed ON public.team_item;
DROP TRIGGER team_item_guard ON public.team_item;
DROP TRIGGER team_item_admit ON public.team_item;
